  ('NTL-M107', 'Multi Mushroom Complex (Reishi, Shiitake, Chaga, Lion''s Mane, Cordyceps, Turkey Tail)', 'Mushroom & Adaptogen Extract', 500, null, null, null, null, '[]', null, 580),
  ('NTL-C101', 'Hydrolyzed Beef Collagen Peptides - 200g', 'Collagen Products', 500, 'powder', 'Net weight 200 g, 10 g per serving, 20 servings', 'Нето 200 г, 10 г на прием, 20 приема', 'Rebuild strength and radiance with our Private Label Hydrolyzed Beef Collagen Peptides, formulated to promote youthful skin, strong hair and nails, joint flexibility, and muscle recovery, featuring highly bioavailable peptides for superior absorption and effectiveness.', '[]', '/catalog/NTL-C101.webp', 590),
  ('NTL-C102', 'Hydrolyzed Marine Collagen Peptides - 150g', 'Collagen Products', 500, 'powder', 'Net weight 150 g, 5 g per serving, 30 servings', 'Нето 150 г, 5 г на прием, 30 приема', 'Enhance beauty and vitality with our Private Label Hydrolyzed Marine Collagen Peptide, formulated to support skin elasticity, hydration, and firmness while promoting healthy hair, nails, and joint mobility with superior bioavailability and purity.', '[]', '/catalog/NTL-C102.webp', 600),
  ('NTL-C103', 'Beauty Collagen Powder (with Vitamin C + Hyaluronic Acid) - 200g', 'Collagen Products', 500, 'powder', 'Net weight 200 g, 10 g per serving, 20 servings', 'Нето 200 г, 10 г на прием, 20 приема', 'Glow from within with our Private Label Beauty Collagen Powder, a rejuvenating blend of Hydrolyzed Collagen, Vitamin C, and Hyaluronic Acid, formulated to support skin elasticity, hydration, and smoothness while promoting healthy hair and nails for a radiant, youthful appearance.', '[]', '/catalog/NTL-C103.webp', 610),
  ('NTL-C104', 'Collagen Complex - 60 Capsules', 'Collagen Products', 500, 'capsule', '2 capsules per serving, 30 servings', '2 капсули на прием, 30 приема', 'Rejuvenate and strengthen from within with our Private Label Collagen Complex, a comprehensive beauty and wellness formula with key skin-nourishing nutrients, supporting collagen synthesis, hydration and healthy hair, skin, and nails.', '[{"name":"Hydrolyzed Bovine Collagen Peptides (Type I & III)","amount":"800 mg"},{"name":"Vitamin C (ascorbic acid)","amount":"120 mg"},{"name":"Hyaluronic Acid (Sodium Hyaluronate)","amount":"80 mg"},{"name":"Silicon (from bamboo extract, 70% silica)","amount":"40 mg"},{"name":"Zinc Bisglycinate","amount":"10 mg"},{"name":"Biotin (Vitamin B7)","amount":"1000 mcg"}]', '/catalog/NTL-C104.webp', 620),
  ('NTL-WM101', 'GLP-1 Support (DNF-10®, Gymnema, Berberine HCL, ACV, Chromium)', 'Metabolic & Weight Management', 500, 'capsule', '2 capsules per serving, 30 servings', '2 капсули на прием, 30 приема', 'Expand your product line with our Private Label GLP-1 Support Formula, designed to support appetite control, metabolic health, and balanced blood sugar levels.', '[{"name":"DNF-10®","amount":"500 mg"},{"name":"Myo-Inositol","amount":"250 mg"},{"name":"Gymnema Sylvestre Extract (25%)","amount":"200 mg"},{"name":"Apple Cider Vinegar Powder (5-6%)","amount":"200 mg"},{"name":"Ceylon Cinnamon Extract (10:1)","amount":"100 mg"},{"name":"Berberine HCl (97%)","amount":"100 mg"},{"name":"Black Pepper Extract (95% Piperine)","amount":"5 mg"},{"name":"Chromium Picolinate","amount":"400 mcg"}]', '/catalog/NTL-WM101.webp', 630),
  ('NTL-WM102', 'Nextida GC GLP-1 Collagen Peptides – 150g', 'Metabolic & Weight Management', 500, 'powder', 'Net weight 150 g, 5 g per serving, 30 servings', 'Нето 150 г, 5 г на прием, 30 приема', 'Introduce a premium innovation with our Private Label Nexida GC GLP-1 Collagen Peptides, an advanced formula combining hydrolyzed collagen with key nutrients designed to support skin elasticity, joint health, and metabolic balance. Developed to complement GLP-1 wellness programs, this unique blend promotes satiety, muscle maintenance, and radiant vitality from within.', '[]', '/catalog/NTL-WM102.webp', 640),
  ('NTL-WM103', 'Apple Cider Vinegar Capsules', 'Metabolic & Weight Management', 500, 'capsule', '2 capsules per serving, 30 servings', '2 капсули на прием, 30 приема', 'Enhance your product line with our Private Label Apple Cider Vinegar Powder Capsules, a convenient and effective way to promote digestive health, support weight management, and maintain energy levels.', '[{"name":"Apple Cider Vinegar Powder","amount":"600 mg"}]', '/catalog/NTL-WM103.webp', 650),
  ('NTL-WM104', 'Citrus Flavonoids Complex', 'Metabolic & Weight Management', 500, null, null, null, null, '[]', null, 660),
  ('NTL-WM105', 'Water Control Formula', 'Metabolic & Weight Management', 500, 'capsule', '2 capsules per serving, 30 servings', '2 капсули на прием, 30 приема', 'Elevate your brand with our Private Label Water Control Formula, a targeted blend of herbal extracts and key minerals designed to support healthy fluid balance, reduce water retention, and promote a lean, defined physique.', '[{"name":"Dandelion Root Extract (4:1)","amount":"300 mg"},{"name":"Birch Leaf Extract (10:1)","amount":"200 mg"},{"name":"Uva Ursi Extract","amount":"150 mg"},{"name":"Horsetail Extract (7% silica)","amount":"100 mg"},{"name":"Magnesium Glycinate","amount":"100 mg"},{"name":"Potassium Citrate","amount":"99 mg"},{"name":"Vitamin B6 (P-5-P)","amount":"5 mg"}]', '/catalog/NTL-WM105.webp', 670),
  ('NTL-WM106', 'Appetite Suppressing Formula', 'Metabolic & Weight Management', 500, 'capsule', '2 capsules per serving, 30 servings', '2 капсули на прием, 30 приема', 'Enhance your product line with our Private Label Appetite Suppressing Formula, a carefully crafted blend designed to help control cravings, support portion control, and promote healthy weight management.', '[{"name":"Glucomannan","amount":"400 mg"},{"name":"Apple Cider Vinegar Powder","amount":"300 mg"},{"name":"Ceylon Cinnamon Extract (10:1)","amount":"200 mg"},{"name":"Green Tea Extract (50% EGCG)","amount":"200 mg"},{"name":"White Willow Bark Extract","amount":"200 mg"},{"name":"Black Pepper Extract (95% Piperine)","amount":"5 mg"},{"name":"Chromium Picolinate","amount":"0.2 mg"}]', '/catalog/NTL-WM106.webp', 680),
  ('NTL-WM107', 'Thermogenic Fat Burning Formula', 'Metabolic & Weight Management', 500, 'capsule', '2 capsules per serving, 30 servings', '2 капсули на прием, 30 приема', 'Boost your product line with our Private Label Thermogenic Formula, a high-performance blend designed to enhance energy, support fat burning, and improve metabolism.', '[{"name":"L-Carnitine Tartrate","amount":"250 mg"},{"name":"Guarana Extract","amount":"200 mg"},{"name":"Green Tea Extract (50% EGCG)","amount":"200 mg"},{"name":"Apple Cider Vinegar Powder","amount":"150 mg"},{"name":"Horsetail Extract (7:1)","amount":"150 mg"},{"name":"Ginger Root Extract (5%)","amount":"100 mg"},{"name":"Black Pepper Extract (95% piperine)","amount":"5 mg"}]', '/catalog/NTL-WM107.webp', 690),
  ('NTL-SP102', 'Whey Protein Matrix + Collagen Blend - 900g', 'Sport & Performance Nutrition', 500, 'powder', 'Net weight 900 g, 30 g per serving, 30 servings', 'Нето 900 г, 30 г на прием, 30 приема', 'Strengthen and restore with our Private Label Whey Protein + Collagen Blend, a powerful combination of high-quality whey protein and collagen, designed to support muscle recovery, joint health, and skin elasticity while providing a smooth, delicious source of complete daily protein.', '[]', '/catalog/NTL-SP102.webp', 700),
  ('NTL-SP103', 'Vegan Protein Powder - 900g', 'Sport & Performance Nutrition', 500, 'powder', 'Net weight 900 g, 30 g per serving, 30 servings', 'Нето 900 г, 30 г на прием, 30 приема', 'Expand your product line with our Private Label Vegan Protein Powder, a premium plant-based formula designed to support muscle recovery, energy, and overall wellness. Made from high-quality vegan protein sources like pea and brown rice, this versatile supplement caters to health-conscious consumers seeking clean and sustainable nutrition. Naturally sweetened with Monk Fruit and Stevia, and enhanced with digestive enzymes for optimal absorption, smooth texture, and gentle digestion.', '[]', '/catalog/NTL-SP103.webp', 710),
  ('NTL-SP104', 'Clear Vegan Protein - 300g', 'Sport & Performance Nutrition', 500, 'powder', 'Net weight 300 g, 10 g per serving, 30 servings', 'Нето 300 г, 10 г на прием, 30 приема', 'Elevate your brand with our Private Label Clear Vegan Protein, a light and hydrating plant-based formula that delivers high-quality protein without the heaviness of traditional shakes, designed to support muscle recovery, lean strength, and daily vitality with a clear finish.', '[]', '/catalog/NTL-SP104.webp', 720),
  ('NTL-SP105', 'Creatine Monohydrate - 300g', 'Sport & Performance Nutrition', 500, 'powder', 'Net weight 300 g, 15 g per serving, 20 servings', 'Нето 300 г, 15 г на прием, 20 приема', 'Boost your product line with our Private Label Creatine Monohydrate designed for athletes and fitness enthusiasts looking to enhance strength, endurance, and recovery. This formula ensures superior solubility and absorption, making it an essential addition to any fitness regimen.', '[]', '/catalog/NTL-SP105.webp', 730),
  ('NTL-SP106', 'Pre-Workout Formula - 300g', 'Sport & Performance Nutrition', 500, 'powder', 'Net weight 300 g, 15 g per serving, 20 servings', 'Нето 300 г, 15 г на прием, 20 приема', 'Elevate your product line with our Private Label Pre-Workout Formula, a high-performance supplement designed to boost energy, enhance focus, and maximize workout endurance. Packed with powerful ingredients like caffeine, beta-alanine, and citrulline malate, this formula is perfect for fitness enthusiasts looking to take their training to the next level.', '[]', '/catalog/NTL-SP106.webp', 740),
  ('NTL-SP107', 'Pre-Workout Stim-Free - 300g', 'Sport & Performance Nutrition', 500, 'powder', 'Net weight 300 g, 15 g per serving, 20 servings', 'Нето 300 г, 15 г на прием, 20 приема', 'Expand your product line with our Private Label Pre-Workout Stim-Free Formula, a high-performance blend designed to enhance endurance, focus, and strength without caffeine or stimulants. Featuring clinically backed ingredients like citrulline malate and beta-alanine, it delivers clean, sustained performance for athletes seeking pure, stimulant-free energy.', '[]', '/catalog/NTL-SP107.webp', 750),
  ('NTL-SP108', 'BCAA - 300g', 'Sport & Performance Nutrition', 500, 'powder', 'Net weight 300 g, 5 g per serving, 60 servings', 'Нето 300 г, 5 г на прием, 60 приема', 'Elevate your brand with our Private Label BCAA Powder, a high-quality blend of branched-chain amino acids (Leucine, Isoleucine, and Valine) designed to support muscle recovery, reduce fatigue, and enhance endurance. Perfect for pre-, intra-, or post-workout supplementation, this versatile product is ideal for fitness enthusiasts and athletes.', '[]', '/catalog/NTL-SP108.webp', 760),
  ('NTL-SP109', 'L-Glutamine - 300g', 'Sport & Performance Nutrition', 500, 'powder', 'Net weight 300 g, 5 g per serving, 60 servings', 'Нето 300 г, 5 г на прием, 60 приема', 'Expand your product line with our Private Label L-Glutamine, a premium amino acid supplement formulated to support muscle recovery, immune function, and gut health. Ideal for athletes and active individuals, this clean and versatile formula helps reduce post-workout fatigue and promotes optimal performance and recovery.', '[]', '/catalog/NTL-SP109.webp', 770),
  ('NTL-SP110', 'Electrolytes - 90g', 'Sport & Performance Nutrition', 500, 'powder', 'Net weight 150 g, 5 g per serving, 30 servings', 'Нето 150 г, 5 г на прием, 30 приема', 'Expand your product line with our Private Label Electrolyte Formula, a balanced blend of essential minerals designed to support optimal hydration, endurance, and recovery. Formulated with key electrolytes, this refreshing mix helps replenish fluids and maintain performance during intense training or daily activity.', '[]', '/catalog/NTL-SP110.webp', 780),
